INSERT INTO internal.pipeline_actions (operation, definition) VALUES
  ('add_analysis_to_notebook', '{"operation":"add_analysis_to_notebook","rpc":"add_analysis_to_notebook","label":"Add an analysis to a notebook","description":"Puts a saved analysis into an experiment’s notebook as a live block: the notebook shows its numbers and plot and keeps them current as the analysis or its data change, and the experiment’s Results tab lists it. Adding the same analysis to the same notebook again returns the block that is already there. Returns the block and `already_there`. Sends `analysis.added_to_notebook`.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_title","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_invitation', '{"operation":"create_invitation","rpc":"create_invitation","label":"Invite someone","description":"Makes an invitation for an email address with a role, optionally for a client (client viewers) and with projects the person joins on accepting: `[{ \"project_id\": \"…\", \"access_level\": \"viewer\" }]`. Returns the invitation and its one-time `token`; the link is `/accept-invitation?token=<token>`. The token is shown once and never stored, so keep it or reissue. Needs members access. Sends `workspace.invitation.created`. In a pipeline the token is left out of the step output.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_email","type":"text","required":true,"nullable":false},{"name":"p_role","type":"text","required":false,"nullable":false},{"name":"p_expires_after_days","type":"integer","required":false,"nullable":false},{"name":"p_client_id","type":"uuid","required":false,"nullable":true},{"name":"p_project_grants","type":"jsonb","required":false,"nullable":false}],"omitFromResult":["token"]}'::jsonb),
  ('list_expiring_materials', '{"operation":"list_expiring_materials","rpc":"list_expiring_materials","label":"List the stock that expires soon","description":"Looks at the materials that expire within `p_days` days (not quarantined, expired, consumed or depleted) and leaves one Inbox item for a person with a line for each lot, soonest first, with no limit on how many. Leaves nothing when nothing expires. Stewards and anyone who can edit in the workspace. Returns `{ count, created, inboxItemId }`. Sends `pipeline.inbox_item.created` when it leaves an item.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false,"server":"workspace"},{"name":"p_user_id","type":"text","required":true,"nullable":false},{"name":"p_days","type":"integer","required":false,"nullable":false}]}'::jsonb),
  ('record_instrument_run_document', '{"operation":"record_instrument_run_document","rpc":"record_instrument_run_document","label":"Keep the Allotrope document of a run","description":"Store the Allotrope document a Python step converted from an instrument file against its instrument run.","arguments":[{"name":"p_run_id","type":"uuid","required":true,"nullable":false},{"name":"p_document","type":"jsonb","required":true,"nullable":false},{"name":"p_converter","type":"text","required":true,"nullable":false},{"name":"p_converter_version","type":"text","required":false,"nullable":true},{"name":"p_image_digest","type":"text","required":false,"nullable":true},{"name":"p_vendor","type":"text","required":false,"nullable":true},{"name":"p_technique","type":"text","required":false,"nullable":true},{"name":"p_manifest","type":"text","required":false,"nullable":true},{"name":"p_measurements","type":"integer","required":false,"nullable":false},{"name":"p_device","type":"jsonb","required":false,"nullable":false}]}'::jsonb),
  ('record_qc_point', '{"operation":"record_qc_point","rpc":"record_qc_point","label":"Add a quality control point","description":"Add a value to a tracked quality control series; it is judged against the series’ limits and rules.","arguments":[{"name":"p_series_id","type":"uuid","required":true,"nullable":false},{"name":"p_value","type":"numeric","required":true,"nullable":false},{"name":"p_at","type":"text","required":false,"nullable":true},{"name":"p_label","type":"text","required":false,"nullable":true},{"name":"p_instrument_run_id","type":"uuid","required":false,"nullable":true}]}'::jsonb),
  ('reissue_invitation', '{"operation":"reissue_invitation","rpc":"reissue_invitation","label":"Send an invitation again","description":"Replaces the link of a pending or expired invitation; the old link stops working. Returns the invitation and its new one-time `token`. Needs members access. In a pipeline the token is left out of the step output.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_invitation_id","type":"uuid","required":true,"nullable":false},{"name":"p_expires_after_days","type":"integer","required":false,"nullable":false}],"omitFromResult":["token"]}'::jsonb),
  ('request_publication', '{"operation":"request_publication","rpc":"request_publication","label":"Prepare a repository draft","description":"Package an experiment or dataset version and send a draft to a publishing repository. A person publishes it from the app.","arguments":[{"name":"p_target_id","type":"uuid","required":true,"nullable":false},{"name":"p_object_kind","type":"text","required":true,"nullable":false},{"name":"p_object_id","type":"uuid","required":true,"nullable":false},{"name":"p_title","type":"text","required":false,"nullable":true},{"name":"p_license","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('set_step_done', '{"operation":"set_step_done","rpc":"set_step_done","label":"Finish or reopen a step","description":"Tick a protocol step as done, or reopen it, with an optional note. Records who finished it and when.","arguments":[{"name":"p_block_id","type":"uuid","required":true,"nullable":false},{"name":"p_done","type":"boolean","required":false,"nullable":false},{"name":"p_note","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('set_study_task_client_visible', '{"operation":"set_study_task_client_visible","rpc":"set_study_task_client_visible","label":"Share a task with the client, or stop","description":"Shows or hides a task on the client portal, with an optional reason. Returns the task.","arguments":[{"name":"p_task_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_client_visible","type":"boolean","required":true,"nullable":false},{"name":"p_reason","type":"text","required":false,"nullable":false}]}'::jsonb)
